    let setup=Instant::now();let mut writer=WideOwnerWriter::new(s.dimension,metric.clone(),config,s.owner_slots,&[0],s.rows,provider.clone(),VectorLimits{append_rows:s.staging_rows,staging_working_bytes:s.staging_working_bytes,split_rows:s.split_rows,split_working_bytes:s.split_working_bytes,workers:s.threads,readers_per_owner:if s.threads>4{s.threads}else{2},..Default::default()})?;writer.set_diagnostic_capacity(s.max_owner_physical_rows,s.construction_observation)?;writer.set_stable_insertion(s.stable_insert)?;
