fn process_memory()->serde_json::Value{let status=fs::read_to_string("/proc/self/status").ok();let field=|name:&str|status.as_ref().and_then(|text|text.lines().find(|line|line.starts_with(name))).and_then(|line|line.split_whitespace().nth(1)).and_then(|v|v.parse::<u64>().ok()).and_then(|v|v.checked_mul(1024));json!({"peak_rss_bytes_linux":field("VmHWM:"),"current_rss_bytes_linux":field("VmRSS:"),"scope":"Linux process status kB converted to bytes; unavailable on other platforms. Not a per-cache allocation bound or physical IO measurement."})}

const JOINED_PHASE_LINE_BYTES:usize=4096;
/// Joined workers have stopped before these counters are sampled. This writes
/// one fixed-shape line and retains no history or record/node identities.
fn joined_phase_progress(stage:&str,phase:u64,rows:usize,native_seconds:f64,counts:&serde_json::Value,messages:&serde_json::Value,cost:&serde_json::Value,times:[f64;5],vector_moves:u64,leaf_moves:Option<u64>,owner_rows:Option<&serde_json::Value>)->Result<()>{
 let mut work=serde_json::Map::new();for key in ["adds","navigates","registers","reassigns","splits","merges","scrubs","scrub_removed","balance_calls","balance_rounds","current_version_requests"]{if let Some(value)=counts.get(key){ensure!(value.is_u64(),"joined counter is not an unsigned integer");work.insert(key.into(),value.clone());}}
 let mut operation_times=serde_json::Map::new();if messages["enabled"].as_bool()==Some(true){if let Some(operations)=messages["operations"].as_object(){for (name,values) in operations{let mut v=serde_json::Map::new();for key in ["calls","queue_ns","service_ns","caller_ns"]{v.insert(key.into(),values[key].clone());}operation_times.insert(name.clone(),serde_json::Value::Object(v));}}}
 let mut structural=serde_json::Map::new();for key in ["outer_acquisitions","reentrant_acquisitions","mutex_wait_elapsed_ns","outer_mutex_hold_elapsed_ns"]{structural.insert(key.into(),cost["structural_mutex"][key].clone());}
 let owner_rows=owner_rows.filter(|v|v.as_array().is_some_and(|rows|rows.len()<=8&&rows.iter().all(|n|n.is_u64())));
 let value=json!({"progress_stage":"joined-phase-summary","event":stage,"phase":phase,"completed_rows":rows,"native_elapsed_seconds":native_seconds,"cumulative_work":work,"cumulative_vector_cost":cost["vectors"],"cumulative_structural_mutex":structural,"cumulative_owner_operations":operation_times,"cumulative_seconds":{"add":times[0],"balance":times[1],"placement":times[2],"copy_nested_add":times[3],"setup":times[4]},"cumulative_placement_vector_moves":vector_moves,"cumulative_placement_leaf_moves":leaf_moves,"current_owner_rows_after_placement":owner_rows,"scope":"Joined phase counters only; no tree/vector scan. Counts retain existing attempt semantics. Owner rows are from the completed catalog placement summary, otherwise null. Collection/serialization/stderr IO is outside algorithm stage timers but included in native/unbucketed elapsed. Queue includes dispatch/setup; caller includes reply scheduling. Operation sums overlap threads and are not wall/CPU fractions. Fetch batch calls are unavailable; logical gets count individual vector requests. Decode time sums existing provider callback observations. Encoded bytes are provider returns, not physical IO. Mutex hold ends immediately before outer release and includes topology flush; active holds absent until released."});let mut line=serde_json::to_vec(&value)?;line.push(b'\n');ensure!(line.len()<=JOINED_PHASE_LINE_BYTES,"joined phase line cap");let mut stderr=std::io::stderr().lock();stderr.write_all(&line)?;stderr.flush()?;Ok(())
}
fn progress(stage:&str,event:&str,completed:usize,elapsed:f64){eprintln!("{}",json!({"progress_stage":stage,"event":event,"completed_rows_or_queries":completed,"native_elapsed_seconds":elapsed}));}
